/* Story by HTML5 UP | html5up.net | @ajlkn | CC BY 3.0.
 * Adapted for ImmichPager; composition, typography and accessibility modified. */
.ip-hero { max-width:1600px; padding:0; }
.ip-hero .ip-header { padding:clamp(32px, 2rem + 3vw, 80px); }
.ip-hero .ip-banner { border-radius:0; }
.ip-title { font-weight:var(--pager-title-font-weight); letter-spacing:-.035em; line-height:1.12; }
.ip-navigation { border-top:1px solid var(--pager-border); }
.ip-block { padding-block:48px; }
@media(max-width:760px) { .ip-hero { padding:0; } .ip-hero .ip-header { padding:32px 24px; } .ip-hero .ip-banner { max-height:420px; } .ip-navigation { padding:24px; } }

.ip-description { opacity:1; }

.ip-albums:not(.tiles) .ip-album-info p { opacity:1; color:var(--pager-muted); }
.ip-albums.tiles .ip-album-info p { opacity:1; color:#ffffff; }
